44	const quotePremium = (items: Item[]): number =>
45	  roundPremiumInMHPCOsFavor(
46	    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
47	      PROCESSING_FEE,
48	  );
